function brandPersona(src){
  const name = String((src && src.brand_name) || '').trim();
  const desc = String((src && src.brand_descriptor) || '').trim();
  if (!name) return 'the brand described in the BRAND CONTEXT below';
  return desc ? (name + ', ' + desc) : name;
}
function brandOnly(src){
  const name = String((src && src.brand_name) || '').trim();
  return name || 'this brand';
}
// Used wherever a prompt previously hardcoded '#ArakLighting'. Derives a
// tag from the brand's own name rather than naming a company that may not
// be the one posting.
function brandTag(src){
  const name = String((src && src.brand_name) || '').trim();
  // Strip an Arabic wordmark in brackets — "Aqeeq (عقيق)" tags as #Aqeeq.
  const latin = name.replace(/\([^)]*\)/g, '').replace(/[^A-Za-z0-9 ]/g, '').trim();
  if (!latin) return '';
  return '#' + latin.split(/\s+/).map(w => w[0].toUpperCase() + w.slice(1)).join('');
}


const rawHttp = this.helpers.httpRequest;

// Retry a lookup that never left the machine.
//
// Observed 2026-08-17: one candidate in a two-candidate generate round died
// with "getaddrinfo ENOTFOUND fal.run" while the OTHER candidate — same node,
// same host, same second — reached fal and returned an image, and the balance
// call to the same domain succeeded either side of it. Docker's embedded
// resolver (127.0.0.11) drops a lookup occasionally; nothing was wrong with
// fal, the key, or the prompt. The visible cost was half a paid round lost to
// a blip the user then has to notice and re-run by hand.
//
// ONLY name resolution is retried, deliberately. A DNS failure proves the
// request never reached the provider, so re-sending it cannot start a second
// paid job. A connection reset or a timeout carries no such proof — the model
// may already be rendering — so those still fail once, loudly, exactly as
// before.
const http = async (opts) => {
  for (let attempt = 0; ; attempt++) {
    try {
      return await rawHttp(opts);
    } catch (e) {
      const code = (e && (e.code || (e.cause && e.cause.code))) || '';
      const msg  = String((e && e.message) || '');
      const isDns = code === 'ENOTFOUND' || code === 'EAI_AGAIN'
        || /getaddrinfo\s+(ENOTFOUND|EAI_AGAIN)/.test(msg);
      if (!isDns || attempt >= 2) throw e;
      await new Promise(r => setTimeout(r, 400 * (attempt + 1)));
    }
  }
};
const ANTHROPIC = $env.ANTHROPIC_API_KEY;

async function req(opts){
  try { return await http(opts); }
  catch (e) {
    const detail = (e && (e.error || (e.response && e.response.data) || e.description)) || null;
    const real = detail
      ? (typeof detail === 'string' ? detail
        : Buffer.isBuffer(detail) ? detail.toString('utf8', 0, 300)
        : (detail.error && detail.error.message) || JSON.stringify(detail).slice(0, 400))
      : (e && e.message) || String(e);
    throw new Error(real);
  }
}

// The reply is asked for bare JSON and usually is. The ways it is not — a
// fence or a sentence around it, `//` comments copied from a template, a raw
// line break inside an Arabic caption, a trailing comma — all used to collapse
// to {}, which reached the board as "no options" with nothing to say why.
// Observed 2026-09-14 on the first captions-from-the-picture run.
function tidyJson(s){
  let out = '', inStr = false, esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inStr) {
      if (esc) { esc = false; out += ch; continue; }
      if (ch === '\\') { esc = true; out += ch; continue; }
      if (ch === '"') { inStr = false; out += ch; continue; }
      // A control character is illegal inside a JSON string; escape it.
      if (ch === '\n') { out += '\\n'; continue; }
      if (ch === '\r') { out += '\\r'; continue; }
      if (ch === '\t') { out += '\\t'; continue; }
      out += ch; continue;
    }
    if (ch === '"') { inStr = true; out += ch; continue; }
    // A comment outside a string runs to the end of its line.
    if (ch === '/' && s[i + 1] === '/') { while (i < s.length && s[i] !== '\n') i++; out += '\n'; continue; }
    out += ch;
  }
  return out.replace(/,(\s*[}\]])/g, '$1');
}
function safeJson(t){
  const c = String(t||'').replace(/```json|```/g,'').trim();
  const m = c.match(/\{[\s\S]*\}/);
  for (const candidate of [c, m && m[0]].filter(Boolean)) {
    try { return JSON.parse(candidate); } catch(_){}
    try { return JSON.parse(tidyJson(candidate)); } catch(_){}
  }
  return {};
}


function deDash(text){
  return String(text == null ? '' : text).split('\n').map(function(line){
    if (/^\s*[\u2014\u2013]+\s*$/.test(line)) return line;
    var sep = /[\u0600-\u06FF]/.test(line) ? '\u060c ' : ', ';
    return line
      .replace(/^(\s*)[\u2014\u2013]+\s*/, '$1')            // opening a line: a bullet, drop it
      .replace(/\s*[\u2014\u2013]+\s*$/, '')                 // closing a line: nothing left to join
      .replace(/\s*[\u2014\u2013]+\s*/g, sep)                // anywhere else: it was punctuation
      .replace(/([,\u060c;:!?.\u2026])\s*[,\u060c]\s+/g, '$1 '); // never double up the punctuation
  }).join('\n');
}

const body     = ($input.first().json.body) || {};
const planIdeaId = body.plan_idea_id || '';
const platform = 'instagram';
const platformName = 'Instagram';
const lang     = body.caption_language || 'both';   // ar | en | both
const format   = body.format || 'feed_image';
const aspectRatio = body.aspect_ratio || '';
const mediaType = body.media_type || 'image';       // image | video | none
const wantsCaption = body.wants_caption !== false;
const instructions = body.instructions || '';

// Captions-only: the planner's captions step runs after the picture exists,
// so image-prompt options would describe a picture that is already made.
// Opt-in so any caller that still wants image prompts keeps getting them.
const captionOnly = body.caption_only === true;

// The finished picture, so the captions describe what is actually in the
// shot. Never a video — a clip is not sent to the model at all; a video
// post is captioned from its brief alone. At most two images: enough for a
// carousel's opening slides without paying for every slide.
const imageUrls = mediaType === 'video' ? [] : (Array.isArray(body.image_urls) ? body.image_urls : [])
  .map(u => String(u || '').trim())
  .filter(u => /^https:\/\//i.test(u))
  .slice(0, 2);

const langRule = lang === 'ar'
  ? 'Write in SAUDI ARABIC (Gulf/Najdi dialect — natural, modern, warm; NOT stiff MSA). Fill the *_ar field; set *_en to "".'
  : lang === 'en'
  ? 'Write in ENGLISH. Fill the *_en field; set *_ar to "".'
  : 'Write BOTH a SAUDI ARABIC version (Gulf/Najdi dialect, not stiff MSA) AND an ENGLISH version, matched in meaning, not word-for-word.';

// CACHED prefix (persona + brand context + language rule) is identical
// across every idea drafted in the same plan, so the 2nd+ call in a
// "create plan" burst reads it at ~10% cost.
const cachedPrefix = `You are a senior social media strategist and copywriter for ${brandPersona(body)}.

You are drafting options for ONE ${platformName} post BEFORE it gets generated — the marketer will pick or edit from what you write here, so give them real, distinct choices rather than three near-identical rewrites.

BRAND CONTEXT:
${instructions || 'No brand profile has been filled in yet — work only from the post facts below and make no claims about the company.'}

LANGUAGE: ${langRule}

${"HOW THE COPY MUST SOUND: like a real person at this brand typed it, not like a model wrote marketing copy.\n1. NEVER use an em dash (\u2014) or an en dash (\u2013). Not in the English, not in the Arabic, not once. Where you would reach for one, use a comma, a full stop, or start a new line. These instructions use dashes freely; the caption you write must not.\n2. Skip the tells. No \"it's not just X, it's Y\". No Elevate, Unlock, Discover, Transform, Redefine, Experience, Seamless, Effortless, Testament, Nestled. No \"in a world where\", no \"say goodbye to\", no \"here's the thing\". No three-adjective chants (\"bold, bright, beautiful\") and no stacked one-word fragments for drama.\n3. Plain words beat grand ones: \"light\" not \"luminance\", \"we built\" not \"we meticulously crafted\". One concrete detail beats three adjectives. A post with nothing to brag about can simply say what the thing is.\n4. Vary the rhythm the way people actually type. A short line, then a longer one. Contractions in English. Saudi Arabic that sounds spoken, never a press release run through a translator.\n5. Ordinary is allowed. If it reads like someone wrote it in two minutes and meant it, it is right."}

${"PRECEDENCE \u2014 when the request and the brand context disagree, resolve in this order:\n1. Brand guardrails always win. Anything the brand context lists as a never-do, a compliance rule, or a hard restriction is absolute \u2014 no request overrides it.\n2. The requester's explicit instruction beats a brand DEFAULT. If they asked for a specific colour, format, angle or tone, do that, even where the brand's usual default differs. A stated ask is a decision, not an oversight.\n3. Brand defaults fill in everything left unspecified \u2014 palette, tone, style, structure.\nWhen you override a brand default under rule 2, say so in one short clause in post_strategy (or the nearest explanatory field) so the choice is explainable.\n\nNEVER state a phone number, booking link, website, address, account handle, price, discount or promotional offer unless it appears verbatim in the BRAND CONTEXT. If none is given, end with a soft call to action (\"book your session\", \"send us a message\") and no specifics. Inventing a contact detail or a price is a serious error."}`;

const postFacts = `POST TOPIC: ${body.topic || ''}
ANGLE: ${body.angle || ''}
TONE: ${body.tone || ''}
OBJECTIVE: ${body.objective || ''}
CALL TO ACTION: ${body.cta || ''}
OCCASION: ${body.occasion || '(none)'}
CONTENT PILLAR: ${body.content_pillar || '(none)'}
FORMAT: ${format} (${mediaType === 'video' ? 'video' : mediaType === 'none' ? 'text only, no media' : 'image'}${aspectRatio ? `, ${aspectRatio} orientation` : ''})
${body.image_idea ? `MARKETER'S OWN VISION FOR THE MEDIA: ${body.image_idea}` : ''}
${imageUrls.length ? `THE FINISHED ${imageUrls.length > 1 ? 'PICTURES ARE' : 'PICTURE IS'} ATTACHED ABOVE. Write every caption for what is actually in ${imageUrls.length > 1 ? 'them' : 'it'} — the real subject, setting, light and mood — and keep it consistent with the topic. Never describe anything that is not visible or stated in the brief, and do not read out text that appears in the image word for word.` : ''}`;

const wantsMedia = mediaType !== 'none' && !captionOnly;
const wantsMotion = mediaType === 'video';

// The template is literal JSON — no `//` notes in it. Models copy a template
// faithfully, and a comment copied into the reply is not JSON. Everything the
// notes used to say lives in the instructions above the template instead.
const captionItem = '{"caption_ar":"","caption_en":""}';
const mediaItem = wantsMotion ? '{"media_prompt":"","motion_prompt":""}' : '{"media_prompt":""}';
const captionSchema = `"caption_options":[${wantsCaption ? [captionItem, captionItem, captionItem].join(',') : ''}]`;
const mediaSchema = `"media_prompt_options":[${wantsMedia ? [mediaItem, mediaItem, mediaItem].join(',') : ''}]`;

// Captions-only must not say "this post has no image": when the picture is
// attached, that line contradicts the one telling the model to describe it.
const mediaLine = wantsMedia
  ? `- 3 genuinely different ${wantsMotion ? 'video' : 'image'} directions for this post's media. Each media_prompt is a vivid, detailed prompt ready to hand to an image${wantsMotion ? '/video cover' : ''} generator — the actual scene, lighting, composition and mood.${wantsMotion ? ' Each motion_prompt says how the still should animate into video — camera move, light behaviour, pacing.' : ''}`
  : captionOnly
    ? '- No image prompts — the picture for this post already exists. Return an empty media_prompt_options array.'
    : '- This post has no image or video — return an empty media_prompt_options array.';

const variableSuffix = `${postFacts}

Write:
${wantsCaption ? '- 3 genuinely different caption options for this post — vary the hook and the structure, not just the wording.' : "- This post has NO caption — return an empty caption_options array."}
${mediaLine}

Return ONLY valid JSON — no markdown fences, no comments, nothing before or after it. Write line breaks inside a caption as \\n. EXACTLY this shape:
{${captionSchema},${mediaSchema}}`;

try {
  const resp = await req({ method:'POST', url:'https://api.anthropic.com/v1/messages',
    headers:{ 'x-api-key':ANTHROPIC, 'anthropic-version':'2023-06-01', 'content-type':'application/json' },
    body:{ model:'claude-sonnet-5', max_tokens:3000, messages:[{ role:'user', content:[
      { type:'text', text: cachedPrefix, cache_control:{ type:'ephemeral' } },
      // Images sit AFTER the cached block, so the brand prefix stays
      // byte-identical across a plan's posts and keeps its cache hit.
      ...imageUrls.map(url => ({ type:'image', source:{ type:'url', url } })),
      { type:'text', text: variableSuffix },
    ] }] },
    json:true });
  if (!resp || resp.type === 'error' || !Array.isArray(resp.content)) {
    throw new Error('Claude draft-copy call failed: ' + (resp && resp.error && resp.error.message ? resp.error.message : JSON.stringify(resp).slice(0, 300)));
  }
  // Claude 5-family models can return a leading `thinking` block even when
  // thinking wasn't explicitly requested — content[0] is NOT reliably the
  // text block, so find it by type instead of indexing.
  const textBlock = resp.content.find(b => b.type === 'text');
  const replyText = String((textBlock && textBlock.text) || '');
  const parsed = safeJson(replyText);
  const captionOptions = (wantsCaption && Array.isArray(parsed.caption_options) ? parsed.caption_options.slice(0, 3) : [])
    .map(o => Object.assign({}, o, { caption_ar: deDash(o && o.caption_ar), caption_en: deDash(o && o.caption_en) }));
  const mediaPromptOptions = wantsMedia && Array.isArray(parsed.media_prompt_options) ? parsed.media_prompt_options.slice(0, 3) : [];
  // Say what came back. This workflow keeps no copy of the reply, so the
  // error on the row is the only place a failed draft can be diagnosed from.
  const replyHint = (replyText.trim()
    ? ` Reply began: "${replyText.replace(/\s+/g, ' ').trim().slice(0, 160)}"`
    : ' The reply had no text.') + (resp.stop_reason === 'max_tokens' ? ' (cut off at max_tokens)' : '');
  if (wantsCaption && !captionOptions.length) throw new Error('No caption options returned by the model.' + replyHint);
  if (wantsMedia && !mediaPromptOptions.length) throw new Error('No media prompt options returned by the model.' + replyHint);
  return { json: { _ok: true, plan_idea_id: planIdeaId, caption_options: captionOptions, media_prompt_options: mediaPromptOptions } };
} catch (err) {
  return { json: { _ok: false, plan_idea_id: planIdeaId, error: (err && err.message) ? err.message : String(err) } };
}
